internal sealed class Store {
    internal readonly string Root; internal Data Value;Dictionary<string,NotePage> noteBaseline;internal void ResetNoteBaseline(){noteBaseline=NoteHistory.Snapshot(Value);} static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
    internal Store(string root){Root=root;Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"Backups"));string path=Path.Combine(root,"state.json");Value=File.Exists(path)?Json.Deserialize<Data>(File.ReadAllText(path)):new Data();Validate(Value);ResetNoteBaseline();}
    internal string AudioPath{get{return Path.Combine(Root,"morning.mp3");}}
    internal void Save(){var history=Value.noteHistory==null?new List<NoteRevision>():Value.noteHistory.ToList();try{NoteHistory.Capture(Value,noteBaseline);Validate(Value);string p=Path.Combine(Root,"state.json"),tmp=p+".tmp";if(File.Exists(p)){string b=Path.Combine(Root,"Backups",DateTime.Now.ToString("yyyy-MM-dd")+".json");if(!File.Exists(b))File.Copy(p,b);}File.WriteAllText(tmp,Json.Serialize(Value),new System.Text.UTF8Encoding(false));if(File.Exists(p))File.Replace(tmp,p,p+".previous");else File.Move(tmp,p);ResetNoteBaseline();}catch{Value.noteHistory=history;throw;}}
    internal void Export(string path){File.WriteAllText(path,Json.Serialize(Value),new System.Text.UTF8Encoding(false));}
    internal void Import(string path){if(new FileInfo(path).Length>8*1024*1024)throw new InvalidDataException("Le fichier est trop volumineux.");var incoming=Json.Deserialize<Data>(File.ReadAllText(path));Validate(incoming);File.WriteAllText(Path.Combine(Root,"Backups","avant-import-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".json"),Json.Serialize(Value));Value.portraits=incoming.portraits;Value.instructions=incoming.instructions;Value.dofus=incoming.dofus;Value.timeBlocks=incoming.timeBlocks;Value.noteHistory=incoming.noteHistory;Value.noticeStates=incoming.noticeStates;Value.notices=incoming.notices;Value.tasks=incoming.tasks;Value.pages=incoming.pages;Value.projectData=incoming.projectData;Value.events=incoming.events;Value.favorites=incoming.favorites;Value.modes=incoming.modes;Value.deleted=incoming.deleted;Value.googlePins=incoming.googlePins;Value.projectTemplates=incoming.projectTemplates;Value.budget=incoming.budget;Value.sportNutrition=incoming.sportNutrition;Value.focus=incoming.focus;Value.inbox=incoming.inbox;Value.habits=incoming.habits;Value.focusHistory=incoming.focusHistory;Save();}
    internal void SetAudio(string source){if(new FileInfo(source).Length>80*1024*1024)throw new InvalidDataException("Le MP3 doit faire moins de 80 Mo.");if(!Path.GetExtension(source).Equals(".mp3",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Choisissez un fichier MP3.");if(Path.GetFullPath(source).Equals(Path.GetFullPath(AudioPath),StringComparison.OrdinalIgnoreCase))return;string temp=AudioPath+".tmp";File.Copy(source,temp,true);if(File.Exists(AudioPath))File.Replace(temp,AudioPath,null);else File.Move(temp,AudioPath);}
    internal static void Validate(Data d){if(d==null||d.tasks==null||d.tasks.Count>10000)throw new InvalidDataException("Sauvegarde de tâches invalide.");SportNutrition.Validate(d);PersonalWorkflows.Validate(d);FocusClock.Validate(d);Finance.Validate(d);ProjectTemplates.Validate(d);GoogleFiles.Validate(d);DeletionHistory.Validate(d);LaunchModes.Validate(d);GlobalSearch.Validate(d);Schedule.Validate(d);ProjectData.Validate(d);ProjectVisuals.Validate(d);HomeLayout.Validate(d.settings);if(d.settings==null)d.settings=new Settings();WorkspaceNext.Validate(d);Appearance.Validate(d.settings);Onboarding.ValidateLocal(d.settings);WidgetModel.Validate(d.settings);if(d.settings.Projects==null||d.settings.Projects.Count==0)d.settings.Projects=new List<string>{"Personnel"};if(d.settings.Links==null)d.settings.Links=new List<QuickLink>();if(d.settings.DisplayName==null)d.settings.DisplayName="";if(String.IsNullOrWhiteSpace(d.settings.AppTitle))d.settings.AppTitle="Mon espace";foreach(var link in d.settings.Links){Uri u;if(link==null||String.IsNullOrWhiteSpace(link.Name)||!Uri.TryCreate(link.Url,UriKind.Absolute,out u)||(u.Scheme!="https"&&u.Scheme!="http"))throw new InvalidDataException("Raccourci invalide : utilisez une adresse https ou http.");}if(d.settings.Music<0||d.settings.Music>100||d.settings.Voice<0||d.settings.Voice>100)throw new InvalidDataException("Volume invalide.");var ids=new HashSet<string>();foreach(var t in d.tasks){DateTime date;if(t==null||String.IsNullOrWhiteSpace(t.title)||t.title.Length>500||!new[]{"todo","doing","done"}.Contains(t.status)||(String.IsNullOrWhiteSpace(t.project)||t.project.Length>80)||!new[]{"Normale","Haute","Basse"}.Contains(t.priority)||(!String.IsNullOrEmpty(t.due)&&!DateTime.TryParseExact(t.due,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out date)))throw new InvalidDataException("Une tâche contient des valeurs invalides.");if(String.IsNullOrEmpty(t.id)||!ids.Add(t.id)){t.id=Guid.NewGuid().ToString();ids.Add(t.id);}t.notes=t.notes??"";t.due=t.due??"";}RetiredCompanionData.Validate(d);WeeklyPlanning.Validate(d);NoteHistory.Validate(d);AutomaticBackups.Validate(d);TaskDependencies.Validate(d);NotificationCenter.Validate(d);DayDashboard.Validate(d);WorkspaceEnhancements.Validate(d);}
    internal static bool ShouldRun(Settings s,bool startup,bool hasAudio,string date){return startup&&hasAudio&&s.AutoMorning&&(!s.OnceDaily||s.LastMorning!=date);}
    internal static string Summary(IEnumerable<WorkTask> tasks,string name=""){var active=tasks.Where(t=>t.status!="done").ToList();string day=DateTime.Today.ToString("yyyy-MM-dd");var due=active.Where(t=>!String.IsNullOrEmpty(t.due)&&String.CompareOrdinal(t.due,day)<=0).ToList();var top=due.Count>0?due:active.Where(t=>t.priority=="Haute").ToList();return "Bonjour"+(String.IsNullOrWhiteSpace(name)?"":" "+name)+". Voici le point sur ta journée. "+due.Count+" tâches à échéance aujourd’hui ou en retard. "+active.Count(t=>t.status=="doing")+" tâches en cours. "+(top.Count>0?"Tes prochaines priorités : "+String.Join(". ",top.Take(3).Select(t=>t.title))+". ":active.Count==0?"Ta liste de tâches est vide. ":active.Count+" tâches à venir. ")+"Les services externes ne sont pas encore connectés. Bonne journée.";}
}

