    void DrawPage(){if(modern!=null){modern.Refresh();return;}while(page.Controls.Count>0){var old=page.Controls[0];page.Controls.Remove(old);old.Dispose();}foreach(var pair in navigation){pair.Value.BackColor=pair.Key==view?Theme.Raised:Theme.Panel;pair.Value.ForeColor=pair.Key==view?Theme.Gold:Theme.Text;}var header=new FlowLayoutPanel{Dock=DockStyle.Top,Height=96,FlowDirection=FlowDirection.TopDown,WrapContents=false};header.Controls.Add(Theme.Label(view=="Aujourd’hui"?"Bonjour"+(String.IsNullOrWhiteSpace(store.Value.settings.DisplayName)?"":" "+store.Value.settings.DisplayName)+".":view,Theme.Title));var date=Theme.Label(DateTime.Now.ToString("dddd d MMMM yyyy",CultureInfo.GetCultureInfo("fr-FR")));date.ForeColor=Theme.Muted;header.Controls.Add(date);
        var body=new Panel{Dock=DockStyle.Fill,AutoScroll=true};page.Controls.Add(body);page.Controls.Add(header);
        if(view=="Réglages"){DrawSettings(body);return;}if(view=="Mes services"){DrawServices(body);return;}if(view=="Mes projets"){DrawProjects(body);return;}
        var toolbar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,WrapContents=false};toolbar.Controls.Add(Theme.Button("+ Nouvelle tâche",delegate{Edit(null);},true));
        if(view=="Mes tâches"){var project=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=150};project.Items.Add("Tous les projets");project.Items.AddRange(AllProjects().Cast<object>().ToArray());project.SelectedItem=String.IsNullOrEmpty(projectFilter)?"Tous les projets":projectFilter;Theme.Input(project);var status=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=150};status.Items.AddRange(new object[]{"Tous les statuts","À faire","En cours","Terminé"});status.SelectedItem=statusFilter;Theme.Input(status);var search=new TextBox{Width=185,Text=query};Theme.Input(search);toolbar.Controls.Add(project);toolbar.Controls.Add(status);toolbar.Controls.Add(search);toolbar.Controls.Add(Theme.Button("Filtrer",delegate{projectFilter=project.SelectedIndex==0?"":project.Text;statusFilter=status.Text;query=search.Text;DrawPage();}));}
        IEnumerable<WorkTask> tasks=store.Value.tasks;if(view=="Aujourd’hui")tasks=tasks.Where(t=>t.status!="done").OrderBy(t=>t.priority=="Haute"?0:1).ThenBy(t=>String.IsNullOrEmpty(t.due)?"9999":t.due);else if(view=="Rappels")tasks=tasks.Where(t=>t.status!="done"&&!String.IsNullOrEmpty(t.due)).OrderBy(t=>t.due);else tasks=tasks.Where(t=>(projectFilter==""||t.project==projectFilter)&&(query==""||t.title.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)&&(statusFilter=="Tous les statuts"||Status(t.status)==statusFilter));
        var grid=Grid(tasks);body.Controls.Add(grid);body.Controls.Add(toolbar);
        if(view=="Aujourd’hui"){var stats=new FlowLayoutPanel{Dock=DockStyle.Top,Height=66};var active=store.Value.tasks.Where(t=>t.status!="done").ToList();foreach(string text in new[]{active.Count+" à faire",active.Count(t=>t.status=="doing")+" en cours",store.Value.tasks.Count(t=>t.status=="done")+" terminées"}){var l=Theme.Label(text,new Font("Georgia",16));l.BackColor=Theme.Raised;l.Padding=new Padding(15,9,15,9);stats.Controls.Add(l);}body.Controls.Add(stats);var quick=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=90,AutoScroll=true};foreach(var link in store.Value.settings.Links){string url=link.Url;var shortcut=Theme.Button("  "+link.Name,delegate{OpenLink(url);});quick.Controls.Add(shortcut);SiteIcons.Bind(shortcut,url);}body.Controls.Add(quick);}}
    static string Status(string status){return status=="done"?"Terminé":status=="doing"?"En cours":"À faire";}
    DataGridView Grid(IEnumerable<WorkTask> tasks){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,BackgroundColor=Theme.Panel,BorderStyle=BorderStyle.None,GridColor=Theme.Line,EnableHeadersVisualStyles=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowTemplate={Height=44}};g.DefaultCellStyle.BackColor=Theme.Panel;g.DefaultCellStyle.ForeColor=Theme.Text;g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(80,61,34);g.DefaultCellStyle.SelectionForeColor=Theme.Text;g.ColumnHeadersDefaultCellStyle.BackColor=Theme.Raised;g.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Muted;g.ColumnHeadersHeight=35;g.Columns.Add("title","Tâche");g.Columns[0].FillWeight=220;g.Columns.Add("project","Projet");g.Columns.Add("status","Statut");g.Columns.Add("due","Échéance");g.Columns.Add("priority","Priorité");g.Columns.Add(new DataGridViewButtonColumn{Name="done",HeaderText="",FlatStyle=FlatStyle.Flat,FillWeight=75});foreach(var task in tasks){DateTime date;string due=DateTime.TryParseExact(task.due,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out date)?date.ToString("dd/MM/yyyy"):"—";int index=g.Rows.Add(task.title,task.project,Status(task.status),due,task.priority,task.status=="done"?"Rouvrir":"Terminer");g.Rows[index].Tag=task;if(task.priority=="Haute")g.Rows[index].Cells[4].Style.ForeColor=Theme.Gold;}
        g.CellDoubleClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex>=0&&e.ColumnIndex!=5)Edit((WorkTask)g.Rows[e.RowIndex].Tag);};g.CellContentClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex>=0&&e.ColumnIndex==5){var task=(WorkTask)g.Rows[e.RowIndex].Tag;task.status=task.status=="done"?"todo":"done";Save();DrawPage();}};
        var menu=new ContextMenuStrip();foreach(string state in new[]{"todo","doing","done"}){string s=state;menu.Items.Add(Status(s),null,delegate{if(g.SelectedRows.Count>0){((WorkTask)g.SelectedRows[0].Tag).status=s;Save();DrawPage();}});}menu.Items.Add("Modifier",null,delegate{if(g.SelectedRows.Count>0)Edit((WorkTask)g.SelectedRows[0].Tag);});menu.Items.Add("Supprimer",null,delegate{if(g.SelectedRows.Count>0)Delete((WorkTask)g.SelectedRows[0].Tag);});g.ContextMenuStrip=menu;g.MouseDown+=delegate(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Right){int row=g.HitTest(e.X,e.Y).RowIndex;if(row>=0){g.ClearSelection();g.Rows[row].Selected=true;}}};return g;}
    internal void Edit(WorkTask task){if(modern!=null){var result=modern.EditTask(task);if(result!=null){if(task!=null)store.Value.tasks.Remove(task);store.Value.tasks.Add(result);if(result.status=="done")Schedule.Complete(store.Value,result);Save();DrawPage();}return;}using(var editor=new TaskForm(task,AllProjects())){if(editor.ShowDialog(this)==DialogResult.OK){if(task!=null)store.Value.tasks.Remove(task);store.Value.tasks.Add(editor.Result);Save();DrawPage();}}}
    void Delete(WorkTask task){if(MessageBox.Show("Supprimer « "+task.title+" » ?","Mon espace",MessageBoxButtons.YesNo)==DialogResult.Yes){store.Value.tasks.Remove(task);Save();DrawPage();}}
    void DrawProjects(Panel parent){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};foreach(string p in AllProjects()){string project=p;var tasks=store.Value.tasks.Where(t=>t.project==p).ToList();var b=Theme.Button(p+"  ·  "+tasks.Count(t=>t.status!="done")+" à faire / "+tasks.Count+" tâches",delegate{projectFilter=project;view="Mes tâches";query="";statusFilter="Tous les statuts";DrawPage();});b.MinimumSize=new Size(550,65);flow.Controls.Add(b);}parent.Controls.Add(flow);}
    void DrawServices(Panel parent){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};flow.Controls.Add(Theme.Label("Connexions à préparer",Theme.Section));foreach(string service in new[]{"Bots et applications","Notifications","Services personnels"}){var l=Theme.Label(service+"   ·   Non connecté");l.Padding=new Padding(15);l.BackColor=Theme.Panel;flow.Controls.Add(l);}var info=Theme.Label("Aucun état fictif : la surveillance et les alertes seront ajoutées\naprès connexion de vos services.");info.ForeColor=Theme.Muted;flow.Controls.Add(info);parent.Controls.Add(flow);}
    void DrawSettings(Panel parent){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};var boot=new CheckBox{Text="Ouvrir à ma connexion Windows",Checked=Program.Startup(),AutoSize=true,Margin=new Padding(0,0,0,22)};boot.CheckedChanged+=delegate{try{Program.SetStartup(boot.Checked);}catch(Exception e){MessageBox.Show(e.Message,"Mon espace");}};flow.Controls.Add(Theme.Button("Personnaliser mon espace",delegate{Personalize();},true));flow.Controls.Add(boot);var auto=new CheckBox{Text="Lancer la routine à ma connexion",Checked=store.Value.settings.AutoMorning,AutoSize=true,Margin=new Padding(0,0,0,22)};auto.CheckedChanged+=delegate{store.Value.settings.AutoMorning=auto.Checked;if(!auto.Checked)CancelCountdown();Save();};flow.Controls.Add(auto);var once=new CheckBox{Text="Une seule routine automatique par jour",Checked=store.Value.settings.OnceDaily,AutoSize=true,Margin=new Padding(0,0,0,22)};once.CheckedChanged+=delegate{store.Value.settings.OnceDaily=once.Checked;Save();};flow.Controls.Add(once);flow.Controls.Add(Theme.Button("Musique & voix",delegate{AudioSettings();}));flow.Controls.Add(Theme.Button("Ouvrir mes sauvegardes",delegate{OpenLink(Path.Combine(store.Root,"Backups"));}));flow.Controls.Add(Theme.Button("Exporter mes tâches",delegate{Export();}));flow.Controls.Add(Theme.Button("Importer une sauvegarde",delegate{Import();}));var label=Theme.Label("Les données restent sur ce PC.\nLes sauvegardes locales ne remplacent pas une copie sur un autre disque.\n\nDouble-cliquez sur une tâche pour la modifier.\nLe clic droit permet de changer son statut ou de la supprimer.");label.ForeColor=Theme.Muted;flow.Controls.Add(label);parent.Controls.Add(flow);}
    
    internal List<string> AllProjects(){return store.Value.settings.Projects.Concat(store.Value.tasks.Select(t=>t.project)).Concat(store.Value.pages.Select(n=>n.project)).Concat(store.Value.projectData.Select(p=>p.name)).Where(p=>!String.IsNullOrWhiteSpace(p)).Distinct().ToList();}
    internal void Personalize(){CancelCountdown();if(modern!=null){if(modern.EditProfile()){Theme.Gold=ColorTranslator.FromHtml(store.Value.settings.Accent);Text=store.Value.settings.AppTitle;Save();DrawPage();}return;}using(var form=new ProfileForm(store.Value.settings,AllProjects())){if(form.ShowDialog(this)!=DialogResult.OK)return;store.Value.settings.DisplayName=form.DisplayName;store.Value.settings.AppTitle=form.AppTitle;store.Value.settings.Accent=form.Accent;store.Value.settings.Projects=form.Projects;store.Value.settings.Links=form.Links;store.Value.settings.Configured=true;Theme.Gold=ColorTranslator.FromHtml(form.Accent);Text=form.AppTitle;brandLabel.Text=form.AppTitle;profileLabel.Text=String.IsNullOrWhiteSpace(form.DisplayName)?"MON ESPACE PERSONNEL":form.DisplayName.ToUpperInvariant();Icon=Theme.Icon();ApplyAccent(this);Save();DrawPage();}}
    void ApplyAccent(Control parent){foreach(Control c in parent.Controls){var b=c as Button;if(b!=null&&(string)b.Tag=="primary"){b.BackColor=Theme.Gold;b.FlatAppearance.BorderColor=Theme.Gold;}ApplyAccent(c);}}

    internal void Export(){using(var d=new SaveFileDialog{Filter="Sauvegarde JSON|*.json",FileName="Mon_espace-"+DateTime.Now.ToString("yyyy-MM-dd")+".json"}){if(d.ShowDialog(this)==DialogResult.OK)try{store.Export(d.FileName);notice.Text="Sauvegarde exportée.";}catch(Exception e){MessageBox.Show(e.Message,"Mon espace");}}}
    internal void Import(){if(modern.IsAttachmentBusy){MessageBox.Show("Attendez la fin de la copie des fichiers.");return;}modern.CancelModeLaunch();using(var d=new OpenFileDialog{Filter="Sauvegarde JSON|*.json"})if(d.ShowDialog(this)==DialogResult.OK&&MessageBox.Show("Remplacer vos tâches par cette sauvegarde ? Une copie des tâches actuelles sera conservée.","Mon espace",MessageBoxButtons.YesNo)==DialogResult.Yes)try{store.Import(d.FileName);DrawPage();notice.Text="Tâches importées.";}catch(Exception e){MessageBox.Show(e.Message,"Import impossible");}}
    void SetVolume(){player.Volume=store.Value.settings.Music/100.0*(speaking?.18:1);}
    internal void Speak(){if(store.Value.settings.PrivacyMode)return;if(speech==null){notice.Text="Ajoutez une voix dans les réglages de langue Windows pour activer la synthèse.";return;}var settings=store.Value.settings;try{if(currentPrompt!=null)speech.SpeakAsyncCancelAll();if(!String.IsNullOrEmpty(settings.VoiceName))speech.SelectVoice(settings.VoiceName);else{var french=speech.GetInstalledVoices().FirstOrDefault(v=>v.Enabled&&v.VoiceInfo.Culture.Name.StartsWith("fr"));if(french!=null)speech.SelectVoice(french.VoiceInfo.Name);}speech.Volume=settings.Voice;speech.Rate=0;speaking=true;SetVolume();currentPrompt=new Prompt(Store.Summary(store.Value.tasks,store.Value.settings.DisplayName));speech.SpeakAsync(currentPrompt);}catch(Exception e){currentPrompt=null;speaking=false;SetVolume();notice.Text="Voix indisponible : "+e.Message;}}
    internal void PlayMorning(){if(store.Value.settings.PrivacyMode)return;try{if(!File.Exists(store.AudioPath)){AudioSettings();if(!File.Exists(store.AudioPath))return;}player.Stop();player.Open(new Uri(store.AudioPath));SetVolume();player.Play();track.Text="Musique du matin · lecture en cours";if(store.Value.settings.Speak)Speak();}catch(Exception e){notice.Text="Musique indisponible : "+e.Message;}}
    internal void Stop(){CancelCountdown();if(speech!=null&&currentPrompt!=null)try{speech.SpeakAsyncCancelAll();}catch(Exception e){notice.Text="Arrêt de la voix indisponible : "+e.Message;}currentPrompt=null;speaking=false;player.Stop();SetVolume();track.Text=File.Exists(store.AudioPath)?"Musique arrêtée · MP3 enregistré sur ce PC":"Choisissez votre MP3 dans Musique & voix.";}
    void StartCountdown(){int remaining=10;cancelRoutine.Visible=true;countdownLabel.Text="Votre routine commence dans 10 secondes.";countdown=new System.Windows.Forms.Timer{Interval=1000};countdown.Tick+=delegate{remaining--;countdownLabel.Text="Votre routine commence dans "+remaining+" secondes.";if(remaining<=0){CancelCountdown();PlayMorning();}};countdown.Start();}
    internal void CancelCountdown(){if(countdown!=null){countdown.Stop();countdown.Dispose();countdown=null;}countdownLabel.Text="";cancelRoutine.Visible=false;}
    internal void OpenSpotify(){try{Process.Start("spotify:");}catch{OpenLink("https://open.spotify.com/");}notice.Text="Spotify ouvert. Lancez DJ Maia depuis Spotify.";}
    static void OpenLink(string url){try{AppLinks.Open(url);}catch(Exception e){MessageBox.Show(e.Message,"Ouverture impossible");}}
    internal void AudioSettings(){Stop();player.Close();if(modern!=null){if(modern.EditAudio(speech)){Save();SetVolume();track.Text=File.Exists(store.AudioPath)?"Musique du matin prête":"Choisissez votre MP3 dans Musique & voix.";}return;}using(var form=new AudioForm(store,speech)){if(form.ShowDialog(this)==DialogResult.OK){Save();SetVolume();track.Text=File.Exists(store.AudioPath)?"Musique du matin prête · MP3 enregistré sur ce PC":"Choisissez votre MP3 dans Musique & voix.";}}}
}

internal sealed class TaskForm:Form {
    TextBox title=new TextBox(),notes=new TextBox{Multiline=true,ScrollBars=ScrollBars.Vertical};ComboBox project=new ComboBox(),priority=new ComboBox(),status=new ComboBox();DateTimePicker due=new DateTimePicker{Format=DateTimePickerFormat.Short,ShowCheckBox=true};WorkTask old;internal WorkTask Result;
