ntrols.Add(speak);flow.Controls.Add(spotify);flow.Controls.Add(Theme.Button("Enregistrer",delegate{store.Value.settings.Music=music.Value;store.Value.settings.Voice=voice.Value;store.Value.settings.VoiceName=voices.SelectedIndex==0?"":voices.Text;store.Value.settings.Speak=speak.Checked;store.Value.settings.OpenSpotify=spotify.Checked;DialogResult=DialogResult.OK;Close();},true));}
