        var projectLabel=Theme.Label("Un nom de projet par ligne.\nLes projets qui contiennent déjà des tâches restent visibles.");projectLabel.Dock=DockStyle.Top;projectLabel.Height=62;projectLabel.AutoSize=false;projects.Dock=DockStyle.Fill;projects.Lines=projectNames.ToArray();Theme.Input(projects);projectPage.Controls.Add(projects);projectPage.Controls.Add(projectLabel);
        links=new DataGridView{Dock=DockStyle.Fill,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Theme.Panel,AllowUserToAddRows=true,AllowUserToDeleteRows=true,RowHeadersVisible=true,GridColor=Theme.Line,EnableHeadersVisualStyles=false};links.DefaultCellStyle.BackColor=Theme.Panel;links.DefaultCellStyle.ForeColor=Theme.Text;links.DefaultCellStyle.SelectionBackColor=Theme.Raised;links.DefaultCellStyle.SelectionForeColor=Theme.Text;links.ColumnHeadersDefaultCellStyle.BackColor=Theme.Raised;links.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Text;links.Columns.Add("name","Nom");links.Columns.Add("url","Adresse https://…");links.Columns[0].FillWeight=90;links.Columns[1].FillWeight=200;foreach(var link in settings.Links)links.Rows.Add(link.Name,link.Url);linkPage.Controls.Add(links);var linkHint=Theme.Label("Ajoutez vos liens. Pour en supprimer un, sélectionnez sa ligne et appuyez sur Suppr.");linkHint.Dock=DockStyle.Top;linkHint.Height=55;linkHint.AutoSize=false;linkPage.Controls.Add(linkHint);
        var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=65,Padding=new Padding(17,10,0,0),FlowDirection=FlowDirection.RightToLeft};bottom.Controls.Add(Theme.Button("Enregistrer",delegate{Commit();},true));var cancel=Theme.Button("Annuler",delegate{DialogResult=DialogResult.Cancel;Close();});bottom.Controls.Add(cancel);CancelButton=cancel;Controls.Add(tabs);Controls.Add(bottom);
    }
    void Commit(){if(String.IsNullOrWhiteSpace(name.Text)||String.IsNullOrWhiteSpace(title.Text)){MessageBox.Show("Indiquez votre prénom et le nom de votre application.","Mon espace");return;}Projects=projects.Lines.Select(p=>p.Trim()).Where(p=>p.Length>0).Distinct().ToList();if(Projects.Count==0||Projects.Count>30||Projects.Any(p=>p.Length>80)){MessageBox.Show("Ajoutez entre 1 et 30 projets, avec des noms de moins de 80 caractères.");return;}links.EndEdit();Links=new List<QuickLink>();foreach(DataGridViewRow row in links.Rows){if(row.IsNewRow)continue;string label=Convert.ToString(row.Cells[0].Value).Trim(),url=Convert.ToString(row.Cells[1].Value).Trim();if(label==""&&url=="")continue;Uri uri;if(label==""||label.Length>60||!Uri.TryCreate(url,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&uri.Scheme!="http")){MessageBox.Show("Chaque raccourci doit avoir un nom et une adresse http ou https valide.");return;}Links.Add(new QuickLink{Name=label,Url=url});}if(Links.Count>30){MessageBox.Show("Vous pouvez ajouter jusqu’à 30 raccourcis.");return;}DialogResult=DialogResult.OK;Close();}
}


